import{z as d,x as E,o as l,c as A,q as i,j as n,D as e,d as r,s as p,S as o,b as t}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"度、连通与割","description":"","frontmatter":{"title":"度、连通与割","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/degree-cut.md","filePath":"cs/degree-cut.md","lastUpdated":1791413859000}'),B={name:"cs/degree-cut.md"};function h(m,a,c,u,D,f){const s=E("Mermaid");return l(),A("div",null,[a[2]||(a[2]=i('<h1 id="度、连通与割" tabindex="-1">度、连通与割 <a class="header-anchor" href="#度、连通与割" aria-label="Permalink to &quot;度、连通与割&quot;">​</a></h1><div class="epigraph"><p>度数是点上的边数；连通问能否走过去；割是拿掉之后图碎成两块的那一组点或边。</p><footer>—— 据 Rosen, Discrete Mathematics and Its Applications；Cormen, Leiserson, Rivest and Stein 整理</footer></div><p>上一课<a href="/cs/graph-definition">图的定义</a>钉死了 \\(G=(V,E)\\)，并定义了路、连通、度数，握手引理点到为止。本课不重写有向无向，也不从「网络流」另起。缺口是：定义还没有变成后课树与遍历要用的结构事实——度为 \\(1\\) 的叶、切掉一点是否仍连通、边割与点割哪更细。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>握手：\\(\\sum_v \\deg(v)=2|E|\\)。于是奇数度顶点有偶数个。缺口因此不是再给 \\(G\\) 下定义，而是把度、连通、割连成一张图：最小度 \\(\\delta(G)\\)、连通度 \\(\\kappa(G)\\)（最小点割大小）、边连通度 \\(\\kappa&#39;(G)\\)，满足 \\(\\kappa\\le\\kappa&#39;\\le\\delta\\)（Whitney 不等式，本课当事实用，不写最长证明）。割点、桥（割边）是 \\(\\kappa=1\\) 或 \\(\\kappa&#39;=1\\) 的见证。</p><p><span class="marginnote">握手引理翻译成大白话：每条边都有两个端点，把所有顶点的度数加起来时，每条边恰好被数了两次，所以总和必是 \\(2|E|\\)，一定是偶数。也正因如此，度数为奇数的顶点必须成双成对地出现——否则总和就成不了偶数。</span></p><p><span class="marginnote">初学者容易以为「割」是在示意图上画一条线穿过图。实际上点割是挑出一个顶点集合、边割是挑出一个边集合，问的是「拿走哪些元素后图碎掉」，数的是被拿走的元素个数，与画法无关。若示意图上的一刀恰好穿过某个顶点，必须先声明数的是点还是边。</span></p><p>下一课树是无环连通图，将得到「恰无环 + 连通 \\(\\Rightarrow\\) 任两边是桥」等刻画。本课先让割有名字。算法（DFS 找割点）不在本课展开。</p><h3 id="割不是「画一条线穿过」" tabindex="-1">割不是「画一条线穿过」 <a class="header-anchor" href="#割不是「画一条线穿过」" aria-label="Permalink to &quot;割不是「画一条线穿过」&quot;">​</a></h3><p>点割是顶点子集，去掉后剩余图不连通（通常要求原图连通、子集不取空或全集）。边割是边子集。示意图上的一刀若切过一个顶点，必须声明数的是点还是边。加权最小割是后课流，本课无权重。</p><p><span class="marginnote">Rosen 用握手、欧拉回路预备（奇度点）。CLRS 附录 B 给连通、割、树的词汇。本课停在无向简单图的度与割；强连通是有向后话，不在本课展开。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>算度、找 \\(\\delta\\)。检查去掉一个点或一条边后分量是否增加。连通分量是极大连通子图；桥不属于任何圈——直觉留给树课用等价定义钉死。有向图的出度入度、弱连通，只声明与无向不同，不展开 Kosaraju。</p>',13)),(l(),n(o,null,{default:e(()=>[p(s,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22G%20%3D%20(V%2C%20E)%22%5D%20--%3E%20DEG%5B%22%E5%BA%A6%E6%95%B0%E4%B8%8E%E6%8F%A1%E6%89%8B%22%5D%0A%20%20G%20--%3E%20CON%5B%22%E8%BF%9E%E9%80%9A%E5%88%86%E9%87%8F%22%5D%0A%20%20CON%20--%3E%20CUT%5B%22%E7%82%B9%E5%89%B2%20%2F%20%E8%BE%B9%E5%89%B2%22%5D%0A%20%20CUT%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E6%97%A0%E7%8E%AF%E5%88%99%E6%A0%91%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[r("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"后课 BFS/DFS 的正确性用分量与距离层；稀疏图 \\(\\delta\\) 小则存在叶状结构。生成树会从每个分量长出来：不连通则没有生成树，只有森林——下一课的语言。握手给欧拉回路「零个或两个奇度点」预备，本课不证欧拉。",-1)),a[5]||(a[5]=t("p",null,"Whitney 不等式 \\(\\kappa\\le\\kappa'\\le\\delta\\) 可以用一个最小实例看清：两个三角形各由三条边围成，再用一条边把两个三角形连起来。",-1)),(l(),n(o,null,{default:e(()=>[p(s,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22A%22%5D%20---%20B%5B%22B%22%5D%0A%20%20A%20---%20C%5B%22C%22%5D%0A%20%20B%20---%20C%0A%20%20C%20---%20D%5B%22D%22%5D%0A%20%20D%20---%20E%5B%22E%22%5D%0A%20%20D%20---%20F%5B%22F%22%5D%0A%20%20E%20---%20F%0A%20%20C%20-.%20%22%E6%A1%A5%EF%BC%9A%E6%8B%BF%E6%8E%89%E5%8D%B3%E6%96%AD%22%20.-%3E%20D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<p><span class="marginnote">数字实例：上图除中间连接处的 \\(C\\)、\\(D\\)（度数 \\(3\\)）外，每个顶点的度数都是 \\(2\\)，故 \\(\\delta=2\\)；但拿掉中间连接处的任一点（\\(C\\) 或 \\(D\\)），图就断成两块，故 \\(\\kappa=1\\)；那条连接边是桥，拿掉它也断，故 \\(\\kappa&#39;=1\\)。代进不等式得 \\(1\\le 1\\le 2\\)，全部取到。可见顶点往往比边「更贵」——断一处边有时只需一个点扛着。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 Menger 定理全文、不把 \\(s\\)-\\(t\\) 最小割当流。平面性、着色与度的 Brooks 界不进主干。无限图不出现。</p><p>后课默认：谈到叶、桥、割点，用本课的度与连通；树是连通无环，将推出 \\(|E|=|V|-1\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>度数和为 \\(2|E|\\)；连通问路，割问去掉后是否破碎。</li><li>\\(\\kappa\\le\\kappa&#39;\\le\\delta\\)；桥与割点是最弱的脆弱处。</li><li>无环连通的特化是下一课树。</li><li>出处：Rosen；CLRS 附录 B。</li></ul>',6))])}const C=d(B,[["render",h]]);export{_ as __pageData,C as default};
